$records = @()
foreach ($line in Get-Content -Encoding UTF8 -LiteralPath $patternFile) {
  if ($line -notmatch '^\|([A-J]\d{2})\|[^|]*\|([^|]+)\|([^|]+)\|') { continue }
  $id=$Matches[1]; $name=$Matches[2].Trim(); $observation=$Matches[3].Trim(); $cat=$id.Substring(0,1); $number=[int]$id.Substring(1,2)
  $angle=$angles[$cat][$number-1]
  $core = '“' + $name + '”在本库中先按' + $categoryNames[$cat] + '处理。它不是单颗星或单一宫位的确定性结论，而是把盘面中“' + $observation + '”作为一个需要组合验证的观察入口。具体分析时，先确认相关宫位、主星、会照、四化、庙旺和运限是否同时出现，再看这些信号是否指向同一个现实主题。当前更适合把它理解为：' + $angle + '。这样可以把盘面语言转换为现实问题，而不把一个术语直接翻译成职业、婚姻、财富或疾病结果。'
  $conditions = '至少应有一个明确的主宫或主轴，能够说明观察对象是谁、事件发生在哪个领域、属于本命还是阶段触发；随后核对对宫、三方四正和相关辅煞，确认是否形成同向结构。若涉及四化，必须先登记年干表或宫干飞化所采用的流派版本；若涉及运限，必须把本命、大限和流年分层。健康相关内容只记录睡眠、恢复、压力、作息、疼痛或检查等现实状态，不把盘面转成医疗诊断。感情、事业和财务也只能写成可能的互动模式，并等待用户用实际经历确认。本卡的第一核对点是“' + $angle + '”，第二核对点是“' + $observation + '”，两者都没有现实对应时不提高结论权重。'
  $multi = '在事业上，它可能表现为任务分配、岗位权限、团队合作、收入兑现或职业节奏的变化；在感情上，可能转译为时间安排、责任分工、边界和共同计划；在社交上，可能表现为客户、同事、朋友或师长带来的机会与成本；在家庭和迁移上，可能表现为居住、照护、跨地域或家庭期待的调整。同一结构若没有亲密关系，也可以落在长期合作、客户合同或项目绑定上；若没有正式工作，也可以落在学习、考试、项目和家庭责任上。对“' + $observation + '”的发散推导，应先从“' + $angle + '”对应的现实场景开始，再根据对宫、三方和运限寻找第二条路径，最后用用户已发生的行为和事件确认哪条路径权重更高。'
  $trigger = '本命只说明长期倾向，大限说明阶段背景，流年和流月只在数据可靠时缩小观察窗口。针对本卡，优先核对是否出现“' + $angle + '”所对应的行为，再看它是否与“' + $observation + '”的盘面主题同时出现。报告中应给出可核对的行为，如责任增加、合作规则改变、收入结构调整、睡眠下降、居住变化或关系边界讨论，并把用户反馈作为校正资料。社交平台案例仅能辅助说明表达方式；本轮登记的案例没有达到核心支持等级，不能替代原典和盘面推理。'
  $sourceText = if($cat -eq 'J'){$jSources[$id]}else{$sources[$cat]}
  $basis = '理论回指：' + $sourceText + '。精确位置：' + $locations[$cat] + '。这些来源支持的是宫位、会照、四化、星曜或运限的观察框架，不证明该结构必然产生某种人生结果。' + $id + '的专属观察角度是“' + $angle + '”；使用时只调用与当前报告方向最相关的少量卡片，并保留来源编号和现实验证点。'
  $nl=[Environment]::NewLine
  $text = ('### ' + $id + '｜' + $name + $nl + $nl + '#### 核心机制' + $nl + $nl + $core + $nl + $nl + '#### 成立前提' + $nl + $nl + $conditions + $nl + $nl + '#### 多领域表现与发散推导' + $nl + $nl + $multi + $nl + $nl + '#### 触发与现实核对' + $nl + $nl + $trigger + $nl + $nl + '#### 依据与使用状态' + $nl + $nl + $basis)
  $records += [PSCustomObject]@{Category=$cat;Id=$id;Name=$name;Text=([string]$text)}
}

$groups=$records | Group-Object Category
foreach($g in $groups){
  $content=('# ' + $categoryNames[$g.Name] + '：深度结构卡' + [Environment]::NewLine + [Environment]::NewLine + '本组只收录通过证据矩阵的项目；未通过证据门禁的传统候选不在此处扩写。' + [Environment]::NewLine + [Environment]::NewLine + [string]::Join([Environment]::NewLine + [Environment]::NewLine, @($g.Group | ForEach-Object {$_.Text})))
  Set-Content -LiteralPath (Join-Path $outRoot "$($fileNames[$g.Name]).md") -Value $content -Encoding UTF8
}
$index=@('# 深度结构卡索引','','正式调用时只按报告方向和命中条件选择3—8条，不加载全部卡片。','')
foreach($g in $groups){$index += ('- ' + $categoryNames[$g.Name] + '：' + $g.Count + ' 条，文件 ' + $fileNames[$g.Name] + '.md')}
$index += ''; $index += '传统候选中未通过精确原文核验的项目已暂缓，不以模板扩写。'
Set-Content -LiteralPath (Join-Path $outRoot 'index.md') -Value $index -Encoding UTF8
Write-Output "deep patterns built: accepted=$($records.Count), deferred=$((120-$records.Count))"
